"use strict";(async()=>{const panel=document.querySelector("[data-decision]");if(!panel)return;const e=s=>String(s??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"})[c]);let guide;try{const response=await fetch("/torbay-drainage-guide/assets/decision-guides.00c031ac9d40.json");if(!response.ok||(guide=(await response.json())[panel.dataset.decision],!guide?.nodes?.[guide.start]))throw Error()}catch{return}let route=[guide.start];const content=panel.querySelector(".decision-content"),back=panel.querySelector("[data-decision-back]");function render(focus=!1){const n=guide.nodes[route[route.length-1]];panel.querySelector(".decision-position").textContent=n.result?"Checks to examine":`Question ${route.length}`,back.disabled=route.length===1,content.innerHTML=n.question?`<h2 tabindex="-1">${e(n.question)}</h2><div class="decision-options">${n.options.map(([label,next])=>`<button type="button" data-next="${e(next)}">${e(label)}</button>`).join("")}</div>`:`<h2 tabindex="-1">${e(n.result)}</h2><p>${e(n.text)}</p><h3>Read the checks and their sources</h3><ul class="check-links">${n.links.map(l=>`<li><a href="${e(l.url)}">${e(l.label)}</a></li>`).join("")}</ul>${n.link?`<p><a class="button" href="${e(n.link)}">Open the application checklist</a></p>`:""}${panel.dataset.decision==="discharge"?'<p><a href="/torbay-drainage-guide/tools/#runoff-comparison">Compare the numerical criteria</a> \xB7 <a href="/torbay-drainage-guide/torbay-requirements/">Read Torbay local criteria</a></p>':""}`,focus&&content.querySelector("h2").focus()}content.addEventListener("click",event=>{const button=event.target.closest("[data-next]");if(!button)return;const next=button.dataset.next;Object.hasOwn(guide.nodes,next)&&(route.push(next),render(!0))}),back.addEventListener("click",()=>{route.length>1&&(route.pop(),render(!0))}),panel.querySelector("[data-decision-reset]").addEventListener("click",()=>{route=[guide.start],render(!0)}),panel.hidden=!1,render()})();
